  --color-onyx: #000000;
  --color-bronze-glow: #f2b98b;
  --color-apricot-highlight: #ffaf7c;
  --color-amber-wash: #d49065;

  /* Typography */
  --font-verlag: 'Verlag', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
